package tv.einthusan.app

import android.content.Context
import android.webkit.WebView
import android.webkit.WebViewClient
import android.os.Handler
import android.os.Looper
import androidx.media3.common.MimeTypes
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withContext
import kotlin.coroutines.resume

/** Reads the video URL generated by Einthusan's normal watch-page scripts. */
internal class WebViewPlaybackResolver(private val context: Context) : PlaybackResolver {
    override suspend fun resolve(movie: CatalogMovie): PlaybackResolution =
        withContext(Dispatchers.Main.immediate) {
            suspendCancellableCoroutine { continuation ->
                val webView = WebView(context)
                val handler = Handler(Looper.getMainLooper())
                var attempts = 0
                var finished = false

                fun finish(result: PlaybackResolution) {
                    if (finished) return
                    finished = true
                    handler.removeCallbacksAndMessages(null)
                    webView.stopLoading()
                    webView.destroy()
                    if (continuation.isActive) continuation.resume(result)
                }

                fun inspectPage() {
                    if (finished) return
                    attempts++
                    webView.evaluateJavascript(
                        """(function() {
                            var button = document.querySelector('#download-content');
                            var video = document.querySelector('video source[src], video[src]');
                            return (button && button.href) || (video && (video.src || video.getAttribute('src'))) || '';
                        })();"""
                    ) { raw ->
                        if (finished) return@evaluateJavascript
                        val url = raw?.trim()?.removeSurrounding("\"")
                            ?.replace("\\u0026", "&")
                        if (!url.isNullOrBlank() && url.startsWith("https://")) {
                            val path = url.substringBefore('?')
                            val mime = when {
                                path.endsWith(".m3u8", true) -> MimeTypes.APPLICATION_M3U8
                                path.endsWith(".mpd", true) -> MimeTypes.APPLICATION_MPD
                                path.endsWith(".mp4", true) -> MimeTypes.VIDEO_MP4
                                else -> null
                            }
                            finish(PlaybackResolution(source = PlaybackSource(
                                url = url,
                                mimeType = mime,
                                requestHeaders = mapOf(
                                    "Referer" to "https://einthusan.tv/movie/watch/${movie.id}/",
                                    "User-Agent" to USER_AGENT
                                )
                            )))
                        } else if (attempts >= MAX_ATTEMPTS) {
                            finish(PlaybackResolution(message =
                                "The movie page loaded, but did not expose a playable video URL. If this title requires sign-in, an authenticated Einthusan session is needed."
                            ))
                        } else {
                            handler.postDelayed({ inspectPage() }, POLL_INTERVAL_MS)
                        }
                    }
                }

                webView.settings.javaScriptEnabled = true
                webView.settings.domStorageEnabled = true
                webView.settings.loadsImagesAutomatically = false
                webView.webViewClient = object : WebViewClient() {
                    override fun onPageFinished(view: WebView, url: String) {
                        inspectPage()
                    }
                }
                continuation.invokeOnCancellation {
                    handler.post {
                        handler.removeCallbacksAndMessages(null)
                        webView.stopLoading()
                        webView.destroy()
                    }
                }
                webView.loadUrl("https://einthusan.tv/movie/watch/${movie.id}/")
                handler.postDelayed({
                    finish(PlaybackResolution(message =
                        "The Einthusan movie page took too long to generate its video URL. Please try again."
                    ))
                }, PAGE_TIMEOUT_MS)
            }
        }

    private companion object {
        const val MAX_ATTEMPTS = 40
        const val POLL_INTERVAL_MS = 500L
        const val PAGE_TIMEOUT_MS = 30000L
        const val USER_AGENT = "Mozilla/5.0 (Linux; Android 10; Android TV) AppleWebKit/537.36 Chrome/120.0 Safari/537.36"
    }
}
